      state <= 2'h0;
      data_pc <= 32'h0;
      data_info_instr <= 32'h0;
      data_info_valid <= 1'h0;
      data_info_op <= 5'h0;
      data_info_reg_wen <= 1'h0;
      data_info_reg_waddr <= 5'h0;
